use super::*;

#[test]
fn compression_matches_independent_decimal_equation_evaluation() {
    // Independent 55-digit Decimal evaluation of the published BM3 polynomial
    // at exact linear compressions, not samples generated by the Rust inverter.
    // These are equation-verification fixtures, not experimental error bars.
    for (x, pressure, rho) in [
        (1.05, 4_263_347_815.643_079, 1_695.077_833_546_908),
        (1.075, 7_407_369_601.265_801, 1_819.060_486_338_057_7),
        (1.1, 11_408_592_138.693_75, 1_948.945_985_488_335_7),
    ] {
        assert!((pressure_at_compression(x) / pressure - 1.0).abs() < 1e-13);
        let result = density(pressure, TEMPERATURE_K).unwrap();
        assert!((result.density_kg_m3 / rho - 1.0).abs() < 1e-11);
    }
}

#[test]
fn fixed_volume_fit_reproduces_published_h2o_lattice_observations_to_fit_accuracy() {
    // Lai et al. (2023), p. 1532: cubic H₂O unit cells, Z=2. These are
    // measured observations, NOT exact verification values for the fitted EOS.
    // The nominal pressures have no stated uncertainties in this paragraph.
    // Fixed-volume BM3 predicts volumes lower by ~0.162% and ~0.321%; neither
    // agreement within lattice error bars nor a general 0.4% accuracy is claimed.
    for (pressure, lattice_angstrom, expected_volume_difference) in [
        (3.5e9, 3.3046_f64, -0.001_623_930_393_799),
        (5.5e9, 3.2510_f64, -0.003_206_390_555_527),
    ] {
        let result = density(pressure, TEMPERATURE_K).unwrap();
        let cell_volume = 2.0 * MOLAR_MASS_KG_MOL / (AVOGADRO_PER_MOL * result.density_kg_m3);
        let observed_volume = (lattice_angstrom * 1e-10).powi(3);
        let difference = cell_volume / observed_volume - 1.0;
        assert!((difference - expected_volume_difference).abs() < 2e-11);
        assert!(difference.abs() < 0.004);
    }
}

#[test]
fn branch_is_bounded_compressive_and_closes_the_requested_pressure() {
    let mut previous = 0.0;
    for i in 0..=165 {
        let pressure = MIN_PRESSURE_PA + f64::from(i) * 100e6;
        let result = density(pressure, TEMPERATURE_K).unwrap();
        assert_eq!(result, density(pressure, TEMPERATURE_K).unwrap());
        assert!(result.density_kg_m3.is_finite() && result.density_kg_m3 > previous);
        assert!(result.pressure_evaluations > 2);
        assert!(result.pressure_evaluations <= MAX_PRESSURE_EVALUATIONS);
        assert!(result.pressure_residual_pa.abs() <= pressure * 1e-11);
        // Independent Eulerian-strain expression checks density-to-pressure
        // closure rather than trusting the inverter's saved residual alone.
        let strain = ((result.density_kg_m3 / REFERENCE_DENSITY_KG_M3).powf(2.0 / 3.0) - 1.0) / 2.0;
        let forward = 3.0
            * BULK_MODULUS_PA
            * strain
            * (1.0 + 2.0 * strain).powf(2.5)
            * (1.0 + 1.5 * (BULK_MODULUS_DERIVATIVE - 4.0) * strain);
        assert!((forward - pressure).abs() <= pressure * 1.01e-11);
        previous = result.density_kg_m3;
    }
}

#[test]
fn unavailable_temperatures_domains_and_exhausted_work_never_return_a_density() {
    for pressure in [
        f64::NAN,
        f64::INFINITY,
        -1.0,
        0.0,
        MIN_PRESSURE_PA - 1.0,
        MAX_PRESSURE_PA + 1.0,
    ] {
        let error = density(pressure, TEMPERATURE_K).unwrap_err();
        assert_eq!(error.reason, Failure::PressureDomain);
        assert_eq!(error.pressure_evaluations, 0);
        assert_eq!(error.pressure_pa.to_bits(), pressure.to_bits());
    }
    for temperature in [
        f64::NAN,
        f64::INFINITY,
        0.0,
        250.0,
        299.999,
        300.001,
        1000.0,
    ] {
        let error = density(5e9, temperature).unwrap_err();
        assert_eq!(error.reason, Failure::TemperatureDomain);
        assert_eq!(error.pressure_evaluations, 0);
        assert_eq!(error.temperature_k.to_bits(), temperature.to_bits());
    }
    let solved = density(5e9, TEMPERATURE_K).unwrap();
    for limit in 0..solved.pressure_evaluations {
        let error = density_with_budget(5e9, TEMPERATURE_K, limit).unwrap_err();
        assert_eq!(error.reason, Failure::EvaluationLimit);
        assert_eq!(error.pressure_evaluations, limit);
    }
    assert_eq!(
        solved,
        density_with_budget(5e9, TEMPERATURE_K, solved.pressure_evaluations).unwrap()
    );
    assert_eq!(
        solved,
        density_with_budget(5e9, TEMPERATURE_K, usize::MAX).unwrap()
    );
    // Explicit density knowledge must not widen equilibrium or liquid APIs.
    assert!(super::super::phase(5e9, TEMPERATURE_K).is_err());
    assert!(super::super::state(5e9, TEMPERATURE_K).is_err());
    assert!(super::super::dense_liquid::state(5e9, TEMPERATURE_K).is_err());
}
